import { assign, fromPromise, setup } from "xstate"
import {
  type Output,
  getNEP141StorageRequired,
} from "../../services/nep141StorageService"
import type { BaseTokenInfo } from "../../types/base"

const storageDepositAmountActor = fromPromise(
  async ({
    input,
  }: {
    input: {
      token: BaseTokenInfo
      userAccountId: string
    }
  }): Promise<Output> => {
    try {
      const result = await getNEP141StorageRequired({
        token: input.token,
        userAccountId: input.userAccountId,
      })
      return result
    } catch {
      return {
        tag: "err",
        value: {
          reason: "ERR_NEP141_STORAGE_CANNOT_FETCH",
        },
      }
    }
  }
)

export interface Context {
  preparationOutput: Output | null
}

export const storageDepositAmountMachine = setup({
  types: {
    context: {} as Context,
    events: {} as {
      type: "REQUEST_STORAGE_DEPOSIT"
      params: {
        token: BaseTokenInfo
        userAccountId: string
      }
    },
  },
  actors: {
    storageDepositAmountActor: storageDepositAmountActor,
  },
}).createMachine({
  /** @xstate-layout -kQ63ctk80VOZzoaAgcGMgNS7T0IIYM2uSOMqPM9ickTCkTU1g8PmxCHs9nZ7msmy88US6FaVOBtx6JAgnzA9L0jIWzPsrlCIq5PJ2QTUllsgRFJ3F50ll2pnSyPXu-TKyrIqpRFkirls0XsOqxu1cwVsbL9TnsMTNlKuNNltgKaEoX3ykEdcyZQUNaycnm5PsQkQJtlclncucJ8XiQA */
  id: "storageDepositAmount",

  context: () => ({
    preparationOutput: null,
  }),

  initial: "idle",

  states: {
    idle: {},

    fetching: {
      invoke: {
        src: "storageDepositAmountActor",

        input: ({ event }) => ({
          token: event.params.token,
          userAccountId: event.params.userAccountId,
        }),

        onDone: {
          target: "completed",
          actions: assign({
            preparationOutput: ({ event }) => event.output,
          }),
        },
        onError: {
          target: "completed",
          actions: assign({
            preparationOutput: {
              tag: "err",
              value: {
                reason: "ERR_NEP141_STORAGE_CANNOT_FETCH",
              },
            },
          }),
          reenter: true,
        },
      },
    },

    completed: {},
  },

  on: {
    REQUEST_STORAGE_DEPOSIT: ".fetching",
  },
})
