import { assign, fromPromise, setup } from "xstate"
import { logger } from "../../logger"
import type { BaseTokenInfo, SupportedChainName } from "../../types/base"
import { assert } from "../../utils/assert"

export type Context = Input & {
  txHash: string | null
  error: ErrorState | null
}

export type Input = {
  chainName: SupportedChainName
  derivedToken: BaseTokenInfo
  balance: bigint
  amount: bigint
  userAddress: string
  depositAddress: string | null
  storageDepositRequired: bigint | null
  solanaATACreationRequired: boolean
  nearBalance: bigint | null
  type: string
}

export type DepositDescription = {
  type: string
  amount: bigint
  userAddress: string
  derivedToken: BaseTokenInfo
}

export type Output =
  | {
      tag: "ok"
      value: {
        txHash: string
        depositDescription: DepositDescription
      }
    }
  | {
      tag: "err"
      value: {
        reason: ErrorReason
      }
    }

export type ErrorReason =
  | "ERR_SUBMITTING_TRANSACTION"
  | "ERR_VERIFYING_TRANSACTION"
  | "ERR_DEPOSIT_PARAMS_INVALID"

export type ErrorState = {
  reason: ErrorReason
  error: Error | null
}

export const depositMachine = setup({
  types: {} as {
    context: Context
    input: Input
    output: Output
    error: Error
  },
  actors: {
    signAndSendTransactions: fromPromise(
      async (_: { input: Input }): Promise<string> => {
        throw new Error("not implemented")
      }
    ),
    validateTransaction: fromPromise(
      async (_: {
        input: Context & { txHash: string }
      }): Promise<boolean> => {
        throw new Error("not implemented")
      }
    ),
  },
  actions: {
    setTxHash: assign({
      txHash: ({ event }) => event.output,
    }),
    logError: (_, params: { error: unknown }) => {
      logger.error(params.error)
    },
    setError: assign({
      error: (_, params: ErrorState) => {
        return params
      },
    }),
  },
  guards: {
    isDepositParamsValid: () => {
      throw new Error("not implemented")
    },
  },
}).createMachine({
  /** @xstate-layout N4IgpgJg5mDOIC5QTABwPawJYBcB0WEANmAMQDaADALqKgbY5boB2dIAHogLQCMAnJTz8ATABZeAZgAcAVlm9pkyQDYVAGhABPRLzV4VlJdLEB2WWKP9+AXxuaUDXAWJlyvWkhBOmrdlwRuMTF+PFVRUxFpaREpaM0dBEtZPEoVeVNTXhFTFX4VOwc0TGdsKBYsFihSCFYwAhYAN3QAa3qylgBBFggAZTAegBUAJwBDFlhRgGNfCapPehLZ--fgtnxHDnCmdAwQBMBfSIoCyxAicEFiXg8D2LI9A1HF1RECklDEakLFUNJTQubMcyAA */
  id: "deposit",

  context: ({ input }) => ({
    ...input,
    txHash: null,
    error: null,
  }),

  initial: "idle",

  output: ({ context }): Output => {
    if (context.txHash != null) {
      return {
        tag: "ok",
        value: {
          txHash: context.txHash,
          depositDescription: {
            type: context.type,
            userAddress: context.userAddress,
            amount: context.amount,
            derivedToken: context.derivedToken,
          },
        },
      }
    }

    if (context.error != null) {
      return {
        tag: "err",
        value: {
          reason: context.error.reason,
        },
      }
    }

    throw new Error("Unexpected output")
  },

  states: {
    idle: {
      always: [
        {
          target: "signing",
          guard: "isDepositParamsValid",
        },
        {
          target: "failed",
          actions: [
            {
              type: "logError",
              params: () => {
                return {
                  error: new Error("Error in deposit params"),
                }
              },
            },
            {
              type: "setError",
              params: () => ({
                reason: "ERR_DEPOSIT_PARAMS_INVALID",
                error: null,
              }),
            },
          ],
        },
      ],
    },

    signing: {
      invoke: {
        id: "signAndSendTransactions",

        input: ({ context }) => context,

        onDone: {
          target: "verifying",
          actions: "setTxHash",
        },
        onError: {
          target: "failed",
          actions: [
            {
              type: "logError",
              params: ({ event }) => ({ error: event }),
            },
            {
              type: "setError",
              params: ({ event }) => {
                return {
                  reason: "ERR_SUBMITTING_TRANSACTION",
                  error: toError(event.error),
                }
              },
            },
          ],
        },
        src: "signAndSendTransactions",
      },
    },

    verifying: {
      invoke: {
        id: "validateTransaction",

        input: ({ context }) => {
          const { txHash, ...rest } = context
          assert(txHash != null, "txHash is null")
          return { ...rest, txHash }
        },

        onDone: {
          target: "completed",
          reenter: true,
        },
        onError: {
          target: "failed",
          actions: [
            {
              type: "logError",
              params: ({ event }) => ({ error: event }),
            },
            {
              type: "setError",
              params: () => ({
                reason: "ERR_VERIFYING_TRANSACTION",
                error: null,
              }),
            },
          ],
        },
        src: "validateTransaction",
      },
    },

    failed: {
      type: "final",
    },

    completed: {
      type: "final",
    },
  },
})

function toError(error: unknown): Error {
  return error instanceof Error ? error : new Error("unknown error")
}
